const copy={
 ko:{layoutIntro:'기기 크기가 달라도 여백과 정렬 기준을 일관되게 유지합니다. 제주여라는 모바일 4열과 8px 간격 체계를 사용합니다.',grid:'모바일 그리드',gridDesc:'4열 · 좌우 24px · 거터 16px',safe:'안전 영역과 화면 구성',safeDesc:'상단 56px / 하단 64px + 기기 안전 영역',spacing:'간격 체계',spacingDesc:'8px 단위로 여백과 요소 사이의 간격을 구성합니다.',breakpoints:'모바일 너비 구간',width:'화면 너비',compact:'작은 화면',standard:'기본 화면',wide:'넓은 모바일 화면',layoutRule:'320–359px에서는 좌우 여백을 16px로 줄일 수 있습니다. 모바일 콘텐츠는 540px를 넘기지 않으며, 긴 문장은 줄바꿈하고 고정 높이로 자르지 않습니다.',icons:'아이콘 규칙',iconsDesc:'Lucide · 24 × 24 viewBox · 2px stroke',sizes:'크기와 터치 영역',sizesDesc:'아이콘 16·20·24·32px / 터치 영역 최소 44px',iconsRule:'UI 아이콘은 Lucide를 사용합니다. 선 굵기와 끝 모양을 변경하지 않고 currentColor로 색상을 연결합니다. 아이콘 버튼에는 기능을 설명하는 aria-label을 지정합니다.',iconsAccess:'장식용 아이콘은 aria-hidden="true"로 숨기고 옆 텍스트로 의미를 전달합니다. 선택 상태를 색상만으로 표현하지 않고 aria-pressed·aria-current와 함께 사용합니다.',radius:'모서리',radiusDesc:'기존 16·24px 기준 유지',border:'경계선',borderDesc:'기본 1px / 강조 2px',elevation:'깊이와 그림자',elevationDesc:'표면 색상과 그림자를 모드별로 조합',states:'상호작용 상태',statesDesc:'모바일에서는 호버 상태를 추가하지 않습니다.',focus:'키보드 포커스',pressed:'누름',disabled:'비활성',normal:'기본',stateRule:'오류에는 설명 문구와 aria-invalid를 함께 제공합니다. 비활성 동작은 실제 disabled 속성을 적용하고, 로딩 상태는 aria-busy로 알립니다.',motion:'전환과 감소된 모션',motionDesc:'기본 180ms · prefers-reduced-motion 존중',layers:'레이어 순서',tokens:'토큰 계층',tokensDesc:'프리미티브 → 시맨틱 → 컴포넌트',primitive:'프리미티브',primitiveDesc:'색상·크기 등 기초 값',semantic:'시맨틱',semanticDesc:'사용 목적에 따른 이름',component:'컴포넌트',componentDesc:'컴포넌트가 소비하는 역할',naming:'이름과 모드',namingDesc:'CSS 변수와 JSON을 같은 기준으로 제공',namingRule:'새 화면은 역할 토큰을 사용합니다. 다크·라이트 전환은 역할의 값을 바꾸며, 프라이머리 #634BFF와 기본 다크 배경 #161525를 유지합니다.',body:'콘텐츠',top:'상단 탐색',bottom:'하단 탐색'},
 en:{layoutIntro:'Keep spacing and alignment consistent across devices. Jejuyeora uses a mobile four-column grid and an 8px spacing scale.',grid:'Mobile grid',gridDesc:'4 columns · 24px margins · 16px gutters',safe:'Safe areas and screen structure',safeDesc:'56px top navigation / 64px bottom navigation + safe areas',spacing:'Spacing scale',spacingDesc:'Use an 8px scale for margins and spacing between elements.',breakpoints:'Mobile width ranges',width:'Viewport width',compact:'Compact',standard:'Standard',wide:'Wide mobile',layoutRule:'Margins may reduce to 16px on 320–359px screens. Cap mobile content at 540px. Wrap long strings and use minimum heights.',icons:'Icon guidelines',iconsDesc:'Lucide · 24 × 24 viewBox · 2px stroke',sizes:'Size and touch targets',sizesDesc:'16·20·24·32px icons / 44px minimum touch target',iconsRule:'Use Lucide UI icons with consistent stroke and round line endings. Use currentColor and provide a functional aria-label for icon buttons.',iconsAccess:'Hide decorative icons with aria-hidden="true" and pair them with readable text. Communicate selection with aria-pressed or aria-current as well as color.',radius:'Corner radius',radiusDesc:'Keep the existing 16·24px values',border:'Borders',borderDesc:'1px standard / 2px emphasis',elevation:'Elevation and shadows',elevationDesc:'Mode-specific surface colors and shadows',states:'Interaction states',statesDesc:'Mobile components do not require hover states.',focus:'Keyboard focus',pressed:'Pressed',disabled:'Disabled',normal:'Enabled',stateRule:'Pair errors with messages and aria-invalid. Disable actions with the disabled attribute and announce loading through aria-busy.',motion:'Motion and reduced motion',motionDesc:'180ms default · respect prefers-reduced-motion',layers:'Layer order',tokens:'Token architecture',tokensDesc:'Primitive → Semantic → Component',primitive:'Primitive',primitiveDesc:'Base colors and dimensions',semantic:'Semantic',semanticDesc:'Names that describe a purpose',component:'Component',componentDesc:'Roles consumed by components',naming:'Naming and color modes',namingDesc:'Consistent CSS variables and JSON data',namingRule:'Use role-based tokens in new screens. Color modes change role values while preserving #634BFF primary and #161525 default dark background.',body:'Content',top:'Top navigation',bottom:'Bottom navigation'},
 zh:{layoutIntro:'在不同设备中保持一致的间距与对齐。济州游啦采用移动端四栏网格与8px间距体系。',grid:'移动端网格',gridDesc:'4栏 · 左右24px · 栏间16px',safe:'安全区域与屏幕结构',safeDesc:'顶部56px / 底部64px + 设备安全区域',spacing:'间距体系',spacingDesc:'使用8px体系设置边距与元素间距。',breakpoints:'移动端宽度范围',width:'屏幕宽度',compact:'紧凑屏幕',standard:'标准屏幕',wide:'宽屏移动设备',layoutRule:'320–359px屏幕可将左右间距缩小至16px。移动内容最大540px。长文本应换行，并使用最小高度。',icons:'图标规范',iconsDesc:'Lucide · 24 × 24 viewBox · 2px线宽',sizes:'尺寸与触控区域',sizesDesc:'图标16·20·24·32px / 触控区域至少44px',iconsRule:'界面使用Lucide图标，保持线宽与圆形端点一致。使用currentColor，并为图标按钮提供描述功能的aria-label。',iconsAccess:'装饰图标使用aria-hidden="true"，通过相邻文本传递含义。选中状态应同时使用aria-pressed或aria-current。',radius:'圆角',radiusDesc:'保留16·24px规范',border:'边框',borderDesc:'标准1px / 强调2px',elevation:'层级与阴影',elevationDesc:'根据外观组合表面颜色与阴影',states:'交互状态',statesDesc:'移动组件无需悬停状态。',focus:'键盘焦点',pressed:'按下',disabled:'禁用',normal:'默认',stateRule:'错误应同时提供说明与aria-invalid。使用disabled禁用操作，并通过aria-busy告知加载状态。',motion:'动效与减少动态',motionDesc:'默认180ms · 遵循prefers-reduced-motion',layers:'层级顺序',tokens:'变量体系',tokensDesc:'基础值 → 语义 → 组件',primitive:'基础变量',primitiveDesc:'基础颜色与尺寸',semantic:'语义变量',semanticDesc:'根据用途命名',component:'组件',componentDesc:'组件使用的语义角色',naming:'命名与外观',namingDesc:'CSS变量与JSON数据保持一致',namingRule:'新页面使用语义变量。切换外观时修改角色值，同时保留主色#634BFF与默认深色背景#161525。',body:'内容',top:'顶部导航',bottom:'底部导航'}
};
const code=s=>`<div class="code-area"><pre><code>${esc(s)}</code></pre></div>`;
export function renderFoundation(item,{lang,ui,t,heading,section,pager,footer}){const x=copy[lang];let html=heading(item.title,item.description[lang],'FOUNDATIONS');
 if(item.id==='layout')html+=`<div class="foundation-panel"><p class="jy-body jy-muted">${x.layoutIntro}</p></div>${section(x.grid,x.gridDesc)}<div class="component-workbench"><div class="workbench-top"><strong>${x.width}</strong><div class="preview-actions"><select id="layout-width" aria-label="${x.width}">${[320,360,375,390,414,540].map(w=>`<option ${w===390?'selected':''}>${w}</option>`).join('')}</select></div></div><div class="workbench-body"><div class="layout-device" id="layout-device"><div class="layout-safe">safe-area-inset-top</div><div class="layout-top">${icon('back',20)}${x.top}${icon('menu',20)}</div><div class="layout-columns"><span class="layout-col">1</span><span class="layout-col">2</span><span class="layout-col">3</span><span class="layout-col">4</span></div><div class="layout-bottom">${icon('home',24)}${icon('map',24)}${icon('heart',24)}${icon('user',24)}</div><div class="layout-safe">safe-area-inset-bottom</div></div></div><div class="variantbar"><span class="jy-small jy-muted" id="layout-metrics">390px · 4 cols · 24px margin · 16px gutter</span></div></div>${section(x.breakpoints)}<div class="foundation-panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>${x.width}</th><th>Layout</th><th>Margin / Gutter</th></tr></thead><tbody><tr><td>320–359px</td><td>${x.compact}</td><td>16 / 16px</td></tr><tr><td>360–413px</td><td>${x.standard}</td><td>24 / 16px</td></tr><tr><td>414–540px</td><td>${x.wide}</td><td>24 / 16px</td></tr></tbody></table></div><p class="doc-note">${x.layoutRule}</p></div>${section(x.safe,x.safeDesc)}${code(`.app {\n  min-height: 100dvh;\n  max-width: var(--jy-content-max);\n  margin-inline: auto;\n  padding-top: env(safe-area-inset-top);\n}\n.app-content {\n  padding: 24px;\n  padding-bottom: calc(88px + env(safe-area-inset-bottom));\n}\n.bottom-navigation {\n  position: fixed;\n  bottom: 0;\n  width: min(100%, 540px);\n  min-height: 64px;\n  padding-bottom: calc(8px + env(safe-area-inset-bottom));\n}`)}${section(x.spacing,x.spacingDesc)}<div class="foundation-panel"><div class="spacing-row">${[0,8,16,24,32,40,48,64].map(n=>`<div class="spacing-item"><i style="--space:${Math.max(1,n)}px"></i><span>${n}px</span></div>`).join('')}</div></div>`;
 if(item.id==='iconography')html+=`${section(x.icons,x.iconsDesc)}<div class="foundation-panel"><p class="jy-body jy-muted">${x.iconsRule}</p><div class="icon-gallery" style="margin-top:24px">${['home','search','heart','pin','map','user','bell','settings','filter','calendar','plus','close','back','arrow','down','globe','image','play','volume','captions','download','copy','info','accessibility'].map(name=>`<div>${icon(name,24)}<span>${name}</span></div>`).join('')}</div></div>${section(x.sizes,x.sizesDesc)}<div class="foundation-demo-grid">${[16,20,24].map(n=>`<div class="foundation-demo-card"><div class="jy-row" style="gap:24px">${icon('heart',n)}<button class="jy-iconbtn fill" aria-label="${t.save}">${icon('heart',n)}</button></div><h3>${n}px icon</h3><p>44px+ touch target</p></div>`).join('')}</div><div class="details-grid"><div class="detail-card"><h3>${icon('accessibility',20)}${ui.access}</h3><p>${x.iconsAccess}</p></div><div class="detail-card"><h3>${icon('code',20)}${ui.usage}</h3>${code(`import { icon } from './components.js';\n\n// Decorative SVG. Name the interactive button.\nbutton.setAttribute('aria-label', '${t.save}');\nbutton.innerHTML = icon('heart', 24);`)}</div></div>`;
 if(item.id==='object-styles')html+=`${section(x.radius,x.radiusDesc)}<div class="foundation-demo-grid">${[['16px','--jy-radius-sm'],['24px','--jy-radius'],['50%','--jy-radius-circle']].map(([n,token])=>`<div class="foundation-demo-card"><div class="style-sample" style="--radius:${n};${n==='50%'?'width:104px;margin-inline:auto':''}">${n}</div><code>${token}</code></div>`).join('')}</div>${section(x.border,x.borderDesc)}<div class="details-grid">${[1,2].map(n=>`<div class="detail-card"><div class="style-sample" style="--border-width:${n}px">${n}px</div><code>--jy-border-${n}</code></div>`).join('')}</div>${section(x.elevation,x.elevationDesc)}<div class="foundation-demo-grid">${[1,2,3].map(n=>`<div class="foundation-demo-card"><div class="style-sample" style="--shadow:var(--jy-shadow-${n})">Elevation ${n}</div><code>--jy-shadow-${n}</code></div>`).join('')}</div>${section(x.states,x.statesDesc)}<div class="foundation-demo-grid"><div class="foundation-demo-card state-example"><strong>${x.normal}</strong>${Button(t.save)}<code>opacity: 1</code></div><div class="foundation-demo-card state-example"><strong>${x.pressed}</strong><div style="opacity:var(--jy-state-pressed)">${Button(t.save)}</div><code>opacity: .85</code></div><div class="foundation-demo-card state-example"><strong>${x.disabled}</strong>${Button(t.save,{disabled:true})}<code>disabled / opacity: .38</code></div></div><div class="details-grid"><div class="detail-card"><h3>${x.focus}</h3><button class="jy-btn" style="outline:3px solid var(--jy-primary-text);outline-offset:4px;margin:8px 0 24px">${t.save}</button><p>${x.stateRule}</p></div><div class="detail-card"><h3>${x.motion}</h3><p>${x.motionDesc}</p>${code(`transition: opacity var(--jy-duration);\n\n@media (prefers-reduced-motion: reduce) {\n  animation-duration: .01ms;\n  transition-duration: .01ms;\n}`)}</div></div>${section(x.layers)}<div class="foundation-panel">${code(`--jy-z-base: 0;\n--jy-z-sticky: 10;\n--jy-z-nav: 20;\n--jy-z-menu: 30;\n--jy-z-overlay: 100;\n--jy-z-modal: 200;\n--jy-z-toast: 300;\n/* Native dialog uses the browser top layer. */`)}</div>`;
 if(item.id==='design-tokens')html+=`${section(x.tokens,x.tokensDesc)}<div class="token-architecture"><div><strong>${x.primitive}</strong><p>${x.primitiveDesc}</p><code>--jy-primary-500<br>#634BFF</code></div><div><strong>${x.semantic}</strong><p>${x.semanticDesc}</p><code>--jy-primary<br>--jy-primary-text</code></div><div><strong>${x.component}</strong><p>${x.componentDesc}</p><code>.jy-btn<br>background: var(--jy-primary)</code></div></div>${section(x.naming,x.namingDesc)}<div class="details-grid"><div class="detail-card"><h3>--jy-{role}-{variant}</h3><p>${x.namingRule}</p><div class="token-list" style="margin-top:24px"><div><code>--jy-primary</code><span>#634BFF</span></div><div><code>--jy-primary-text</code><span>Dark / Light</span></div><div><code>--jy-text</code><span>Dark / Light</span></div><div><code>--jy-link</code><span>Accessible link</span></div></div></div><div class="detail-card"><h3>CSS / JSON</h3>${code(`@import './tokens.css';\n@import './jy-ui.css';\n@import './extensions.css';\n\n// Machine-readable tokens\nfetch('./tokens.json');`)}</div></div>`;
 return html+pager(item.id)+footer();
}
